use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Config {
    #[serde(default)]
    pub refresh: RefreshConfig,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RefreshConfig {
    #[serde(default = "default_auto_refresh")]
    pub auto_refresh: bool,

    #[serde(default = "default_refresh_interval")]
    pub refresh_interval: u64,

    #[serde(default = "default_auto_fetch")]
    pub auto_fetch: bool,

    #[serde(default = "default_fetch_interval")]
    pub fetch_interval: u64,
}

fn default_auto_refresh() -> bool { true }
fn default_refresh_interval() -> u64 { 10 }
fn default_auto_fetch() -> bool { true }
fn default_fetch_interval() -> u64 { 60 }

impl Default for Config {
    fn default() -> Self {
        Self {
            refresh: RefreshConfig {
                auto_refresh: true,
                refresh_interval: 10,
                auto_fetch: true,
                fetch_interval: 60,
            },
        }
    }
}

impl Config {
    pub fn load() -> Self {
        let mut config = Self::default();
        if let Some(config_dir) = dirs::config_dir() {
            let config_path = config_dir.join("keifu").join("config.toml");
            if config_path.exists() {
                if let Ok(content) = std::fs::read_to_string(&config_path) {
                    if let Ok(parsed) = toml::from_str::<Config>(&content) {
                        config = parsed;
                    }
                }
            }
        }
        // Clamp minimum intervals as documented
        if config.refresh.refresh_interval < 1 {
            config.refresh.refresh_interval = 1;
        }
        if config.refresh.fetch_interval < 10 {
            config.refresh.fetch_interval = 10;
        }
        config
    }
}
EOF"}

