        let commits = load_commits(&repo)?;
        let graph_rows = GraphBuilder::build_rows(&commits);

        let mut app = Self {
            repo,
            repo_info,
            commits,
            graph_rows,
            selected_commit_idx: 0,
            active_branch_idx: 0,
            mode: Mode::Normal,

            search_query: String::new(),
            search_results: Vec::new(),
            search_selected_idx: 0,

            new_branch_input: String::new(),

            status_msg: None,

            config,
            last_refresh: Instant::now(),
            last_fetch: Instant::now(),

            current_diff: None,
            diff_cached_idx: None,
        };

        app.update_diff();
        Ok(app)
    }

    pub fn refresh_state(&mut self) {
        if let Ok(commits) = load_commits(&self.repo) {
            self.commits = commits;
            self.graph_rows = GraphBuilder::build_rows(&self.commits);
            if self.selected_commit_idx >= self.commits.len() {
                self.selected_commit_idx = self.commits.len().saturating_sub(1);
            }
            self.repo_info.current_branch_name = crate::git::get_current_branch_name(&self.repo);
            self.update_diff();
        }
        self.last_refresh = Instant::now();
    }

    pub fn update_diff(&mut self) {
        if self.commits.is_empty() {
            self.current_diff = None;
            self.diff_cached_idx = None;
            return;
        }

        if self.diff_cached_idx == Some(self.selected_commit_idx) {
            return;
        }

        let commit_item = &self.commits[self.selected_commit_idx];
        if let Ok(diff) = get_diff_summary(&self.repo, commit_item) {
            self.current_diff = Some(diff);
            self.diff_cached_idx = Some(self.selected_commit_idx);
        } else {
            self.current_diff = None;
            self.diff_cached_idx = None;
        }
    }

    pub fn move_down(&mut self) {
        if !self.commits.is_empty() && self.selected_commit_idx < self.commits.len() - 1 {
            self.selected_commit_idx += 1;
            self.active_branch_idx = 0;
            self.update_diff();
        }
    }

    pub fn move_up(&mut self) {
        if self.selected_commit_idx > 0 {
            self.selected_commit_idx -= 1;
            self.active_branch_idx = 0;
            self.update_diff();
        }
    }

    pub fn jump_next_branch(&mut self) {
        if let Some(idx) = self
            .commits
            .iter()
            .enumerate()
            .skip(self.selected_commit_idx + 1)
            .position(|(_, c)| !c.branches.is_empty())
        {
            self.selected_commit_idx += 1 + idx;
            self.active_branch_idx = 0;
            self.update_diff();
        }
    }

    pub fn jump_prev_branch(&mut self) {
        if let Some(idx) = self
            .commits
            .iter()
            .take(self.selected_commit_idx)
            .rposition(|c| !c.branches.is_empty())
        {
            self.selected_commit_idx = idx;
            self.active_branch_idx = 0;
            self.update_diff();
        }
    }

    pub fn jump_to_head(&mut self) {
        if let Some(idx) = self.commits.iter().position(|c| c.is_head) {
            self.selected_commit_idx = idx;
            self.active_branch_idx = 0;
            self.update_diff();
        }
    }

    pub fn move_left_branch(&mut self) {
        if self.active_branch_idx > 0 {
            self.active_branch_idx -= 1;
        }
    }

    pub fn move_right_branch(&mut self) {
        if !self.commits.is_empty() {
            let num_branches = self.commits[self.selected_commit_idx].branches.len();
            if num_branches > 0 && self.active_branch_idx < num_branches - 1 {
                self.active_branch_idx += 1;
            }
        }
    }

    pub fn perform_checkout(&mut self) {
        if self.commits.is_empty() {
            return;
        }

        let commit_item = self.commits[self.selected_commit_idx].clone();
        let branch_label = commit_item.branches.get(self.active_branch_idx);

        match checkout_branch_or_commit(&self.repo, &commit_item, branch_label) {
            Ok(msg) => {
                self.status_msg = Some((msg, false));
                self.refresh_state();
            }
            Err(e) => {
                self.mode = Mode::Error(e.to_string());
            }
        }
    }

    pub fn perform_create_branch(&mut self) {
        let name = self.new_branch_input.trim().to_string();
        self.new_branch_input.clear();
        self.mode = Mode::Normal;

        if name.is_empty() || self.commits.is_empty() {
            return;
        }

        let commit_item = &self.commits[self.selected_commit_idx];
        let target_oid = match commit_item.oid {
            Some(oid) => oid,
            None => {
                if let Ok(head) = self.repo.head() {
                    if let Some(target) = head.target() {
                        target
                    } else {
                        return;
                    }
                } else {
                    return;
                }
            }
        };

        match create_branch(&self.repo, &name, target_oid) {
            Ok(_) => {
                self.refresh_state();
            }
            Err(_) => {
                self.mode = Mode::Error(format!("Failed to create branch '{}'", name));
            }
        }
    }

    pub fn perform_delete_branch(&mut self) {
        self.mode = Mode::Normal;
        if self.commits.is_empty() {
            return;
        }

        let commit_item = &self.commits[self.selected_commit_idx];
        if let Some(label) = commit_item.branches.get(self.active_branch_idx) {
            if let Some(ref local_name) = label.local_name {
                if label.is_head {
                    return; // Cannot delete HEAD branch
                }
                match delete_branch(&self.repo, local_name) {
                    Ok(_) => {
                        self.refresh_state();
                    }
                    Err(e) => {
                        self.mode = Mode::Error(e.to_string());
                    }
                }
            }
        }
    }

    pub fn update_search(&mut self) {
        self.search_results.clear();
        if self.search_query.is_empty() {
            // Show all branches
            let mut all_branches = Vec::new();
            for c in &self.commits {
                for b in &c.branches {
                    let label = b.local_name.clone().unwrap_or_else(|| b.display_label.clone());
                    if !all_branches.contains(&label) {
                        all_branches.push(label);
                    }
                }
            }
            self.search_results = all_branches;
        } else {
            let query = self.search_query.to_lowercase();
            let mut matches = Vec::new();

            for c in &self.commits {
                for b in &c.branches {
                    let label = b.local_name.clone().unwrap_or_else(|| b.display_label.clone());
                    if is_fuzzy_match(&query, &label.to_lowercase()) {
                        if !matches.contains(&label) {
                            matches.push(label);
                        }
                    }
                }
            }
            self.search_results = matches;
        }

        if self.search_selected_idx >= self.search_results.len() {
            self.search_selected_idx = self.search_results.len().saturating_sub(1);
        }
    }

    pub fn confirm_search_selection(&mut self) {
        if let Some(branch_name) = self.search_results.get(self.search_selected_idx) {
            // Find commit that contains this branch
            for (idx, commit) in self.commits.iter().enumerate() {
                for b in &commit.branches {
                    let label = b.local_name.as_ref().unwrap_or(&b.display_label);
                    if label == branch_name {
                        self.selected_commit_idx = idx;
                        self.update_diff();
                        break;
                    }
                }
            }
        }
        self.mode = Mode::Normal;
    }
}

fn is_fuzzy_match(query: &str, target: &str) -> bool {
    if target.contains(query) {
        return true;
    }
    let mut target_chars = target.chars();
    for q in query.chars() {
        if !target_chars.any(|t| t == q) {
            return false;
        }
    }
    true
}
