        Mode::NewBranch => draw_new_branch_popup(f, app, f.area()),
        Mode::ConfirmDelete => draw_confirm_delete_popup(f, app, f.area()),
        _ => {}
    }
}

fn draw_commits_panel(f: &mut Frame, app: &mut App, area: Rect) {
    let block = Block::default()
        .title("Commits")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::DarkGray));

    let inner = block.inner(area);
    f.render_widget(block, area);

    if app.commits.is_empty() {
        return;
    }

    let list_height = inner.height as usize;
    let mut start_idx = 0;
    if app.selected_commit_idx >= list_height {
        start_idx = app.selected_commit_idx - list_height + 1;
    }
    let end_idx = (start_idx + list_height).min(app.commits.len());

    let available_width = inner.width as usize;

    let mut items = Vec::new();

    for i in start_idx..end_idx {
        let commit = &app.commits[i];
        let graph_row = &app.graph_rows[i];
        let is_selected = i == app.selected_commit_idx;

        let mut spans = Vec::new();

        // 1. Graph prefix
        for cell in &graph_row.cells {
            spans.push(Span::styled(
                cell.symbol.to_string(),
                Style::default().fg(cell.color),
            ));
        }
        spans.push(Span::raw(" "));

        // 2. Branch label
        if !commit.branches.is_empty() {
            let active_branch = commit.branches.get(commit.active_branch_idx);
            let display_text = if let Some(b) = active_branch {
                &b.display_label
            } else {
                &commit.branches[0].display_label
            };

            let label_str = if commit.branches.len() > 1 {
                format!("[{}] +{}", display_text, commit.branches.len() - 1)
            } else {
                format!("[{}]", display_text)
            };

            spans.push(Span::styled(
                label_str,
                Style::default()
                    .fg(Color::Indexed(12))
                    .add_modifier(Modifier::BOLD),
            ));
            spans.push(Span::raw(" "));
        }

        // 3. Summary
        spans.push(Span::raw(commit.summary.clone()));

        // Combine into line to calculate width
        let mut left_line = Line::from(spans);

        // Right side info: Date, Author, Hash
        let date_str = &commit.date;
        let author_str = &commit.author_name;
        let hash_str = &commit.short_oid;

        let date_span = Span::styled(date_str.clone(), Style::default().fg(Color::DarkGray));
        let author_span = Span::styled(
            format!("{:8}", author_str.chars().take(8).collect::<String>()),
            Style::default().fg(Color::Cyan),
        );
        let hash_span = Span::styled(hash_str.clone(), Style::default().fg(Color::Yellow));

        // Check horizontal space
        let mut line_spans = left_line.spans;

        if available_width >= 89 {
            // Show all: Date, Author, Hash
            let current_len: usize = line_spans.iter().map(|s| s.width()).sum();
            let right_width = 2 + 10 + 2 + 8 + 2 + 7 + 1; // 32
            if current_len + right_width < available_width {
                let pad = available_width - current_len - right_width;
                line_spans.push(Span::raw(" ".repeat(pad)));
                line_spans.push(Span::raw("  "));
                line_spans.push(date_span);
                line_spans.push(Span::raw("  "));
                line_spans.push(author_span);
                line_spans.push(Span::raw("  "));
                line_spans.push(hash_span);
                line_spans.push(Span::raw(" "));
            }
        } else if available_width >= 81 {
            // Show Date, Author
            let current_len: usize = line_spans.iter().map(|s| s.width()).sum();
            let right_width = 2 + 10 + 2 + 8 + 1; // 23
            if current_len + right_width < available_width {
                let pad = available_width - current_len - right_width;
                line_spans.push(Span::raw(" ".repeat(pad)));
                line_spans.push(Span::raw("  "));
                line_spans.push(date_span);
                line_spans.push(Span::raw("  "));
                line_spans.push(author_span);
                line_spans.push(Span::raw(" "));
            }
        } else if available_width >= 69 {
            // Show Author
            let current_len: usize = line_spans.iter().map(|s| s.width()).sum();
            let right_width = 2 + 8 + 1; // 11
            if current_len + right_width < available_width {
                let pad = available_width - current_len - right_width;
                line_spans.push(Span::raw(" ".repeat(pad)));
                line_spans.push(Span::raw("  "));
                line_spans.push(author_span);
                line_spans.push(Span::raw(" "));
            }
        }

        let mut row_style = Style::default();
        if is_selected {
            row_style = row_style.bg(Color::DarkGray);
        }

        items.push(ListItem::new(Line::from(line_spans)).style(row_style));
    }

    let list = List::new(items);
    f.render_widget(list, inner);

    // Render floating Branches dropdown if selected commit has multiple branches
    if !app.commits.is_empty() {
        let sel_commit = &app.commits[app.selected_commit_idx];
        if sel_commit.branches.len() > 1 {
            draw_branches_dropdown(f, app, area);
        }
    }
}

fn draw_branches_dropdown(f: &mut Frame, app: &App, area: Rect) {
    let sel_commit = &app.commits[app.selected_commit_idx];
    let max_len = sel_commit
        .branches
        .iter()
        .map(|b| b.display_label.len())
        .max()
        .unwrap_or(10);

    let popup_width = (max_len + 6).max(18) as u16;
    let popup_height = (sel_commit.branches.len() + 2).min(10) as u16;

    if area.width < popup_width + 4 {
        return;
    }

    let popup_rect = Rect {
        x: area.width - popup_width - 2,
        y: area.y + 2,
        width: popup_width,
        height: popup_height,
