fn draw_status_line(f: &mut Frame, app: &App, area: Rect) {
    let mut left_spans = vec![
        Span::raw(" "),
        Span::styled(&app.repo_info.repo_name, Style::default().fg(Color::White)),
        Span::raw("   "),
        Span::styled(
            &app.repo_info.current_branch_name,
            Style::default().fg(Color::Green),
        ),
        Span::raw("   "),
    ];

    let mut right_tag = "";
    let mut right_color = Color::Yellow;

    if let Mode::Error(ref err) = app.mode {
        left_spans.push(Span::styled(
            format!("{}    Esc/Enter close", err),
            Style::default().fg(Color::Red),
        ));
        right_tag = "ERROR";
        right_color = Color::Red;
    } else if let Some((ref msg, is_err)) = app.status_msg {
        let color = if is_err { Color::Red } else { Color::White };
        left_spans.push(Span::styled(msg, Style::default().fg(color)));
        if is_err {
            right_tag = "ERROR";
            right_color = Color::Red;
        }
    } else {
        let hint = match app.mode {
            Mode::Normal => "j/k move  Enter checkout  b branch  f fetch  ? help  q quit",
            Mode::Search => "Enter confirm  Esc cancel",
            Mode::NewBranch => "Enter confirm  Esc cancel",
            Mode::ConfirmDelete => "y yes  n no",
            Mode::Help => "Esc/q close help",
            Mode::Error(_) => "",
        };

        match app.mode {
            Mode::Search | Mode::NewBranch => {
                right_tag = "INPUT";
                right_color = Color::Yellow;
            }
            Mode::ConfirmDelete => {
                right_tag = "CONFIRM";
                right_color = Color::Yellow;
            }
            Mode::Help => {
                right_tag = "HELP";
                right_color = Color::Cyan;
            }
            _ => {}
        }

        left_spans.push(Span::styled(hint, Style::default().fg(Color::DarkGray)));
    }

    let left_line = Line::from(left_spans);
    f.render_widget(Paragraph::new(left_line), area);

    if !right_tag.is_empty() {
        let right_paragraph = Paragraph::new(Line::from(vec![
            Span::styled(right_tag, Style::default().fg(right_color).add_modifier(Modifier::BOLD)),
