mod app;
mod config;
mod git;
mod graph;
mod ui;

use app::{App, Mode};
use crossterm::{
    event::{self, Event, KeyCode, KeyEventKind, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{backend::CrosstermBackend, Terminal};
use std::{io, path::Path, time::{Duration, Instant}};

fn parse_cli_args() -> Result<(), anyhow::Error> {
    let args: Vec<String> = std::env::args().collect();
    let bin_name = args.first().map(|s| s.as_str()).unwrap_or("executable");
    let bin_name = Path::new(bin_name)
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("executable");

    if args.len() > 1 {
        for arg in &args[1..] {
            match arg.as_str() {
                "-h" | "--help" => {
                    println!("A TUI tool to visualize Git commit graphs with branch genealogy\n");
                    println!("Usage: {}\n", bin_name);
                    println!("Options:");
                    println!("  -h, --help     Print help");
                    println!("  -V, --version  Print version");
                    std::process::exit(0);
                }
                "-V" | "--version" => {
                    println!("keifu 0.2.3");
                    std::process::exit(0);
                }
                other => {
                    eprintln!("error: unexpected argument '{}' found\n", other);
                    eprintln!("Usage: {}\n", bin_name);
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                }
            }
        }
    }
    Ok(())
}

fn main() -> anyhow::Result<()> {
    parse_cli_args()?;

    let mut app = App::new()?;

    // Terminal setup
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let result = run_app(&mut terminal, &mut app);

    // Restore terminal
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    result
}

fn run_app<B: ratatui::backend::Backend>(
    terminal: &mut Terminal<B>,
    app: &mut App,
) -> anyhow::Result<()> {
    loop {
        terminal.draw(|f| ui::draw_ui(f, app))?;

        // Auto-refresh & auto-fetch background checks
        let now = Instant::now();
        if app.config.refresh.auto_refresh
            && now.duration_since(app.last_refresh)
                >= Duration::from_secs(app.config.refresh.refresh_interval)
        {
            app.refresh_state();
        }

        if app.config.refresh.auto_fetch
            && now.duration_since(app.last_fetch)
                >= Duration::from_secs(app.config.refresh.fetch_interval)
        {
            if let Ok(msg) = crate::git::fetch_origin() {
                app.status_msg = Some((msg, false));
                app.refresh_state();
            }
            app.last_fetch = Instant::now();
        }

        if event::poll(Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                if key.kind != KeyEventKind::Press {
                    continue;
                }

                // Clear status message on key press if not error mode
                if app.mode != Mode::Error(String::new()) && app.status_msg.is_some() {
                    app.status_msg = None;
                }

                match &app.mode {
                    Mode::Normal => match (key.code, key.modifiers) {
                        (KeyCode::Char('q'), KeyModifiers::NONE) | (KeyCode::Esc, _) => break,
