{"command":"cat << 'EOF' > src/graph.rs
use ratatui::style::Color;
use git2::Oid;

pub const BRANCH_COLORS: &[Color] = &[
    Color::Indexed(12), // LightBlue
    Color::Indexed(2),  // Green
    Color::Indexed(5),  // Magenta
    Color::Indexed(3),  // Yellow
    Color::Indexed(1),  // Red
    Color::Indexed(14), // LightCyan
    Color::Indexed(10), // LightGreen
    Color::Indexed(13), // LightMagenta
];

#[derive(Debug, Clone)]
pub struct GraphCell {
    pub symbol: char,
    pub color: Color,
}

#[derive(Debug, Clone)]
pub struct GraphRow {
    pub cells: Vec<GraphCell>,
}

pub struct GraphBuilder {
    lanes: Vec<Option<Oid>>,
}

impl GraphBuilder {
    pub fn new() -> Self {
        Self { lanes: Vec::new() }
    }

    pub fn build_rows(commits: &[crate::git::CommitItem]) -> Vec<GraphRow> {
        let mut builder = Self::new();
        let mut rows = Vec::new();

        for commit in commits {
            rows.push(builder.process_commit(commit));
        }

        rows
    }

    fn process_commit(&mut self, commit: &crate::git::CommitItem) -> GraphRow {
        let oid_opt = commit.oid;

        // Find existing lane for this commit, or allocate a new lane
        let commit_lane = if let Some(oid) = oid_opt {
            if let Some(idx) = self.lanes.iter().position(|l| *l == Some(oid)) {
                idx
            } else {
                // Find empty slot or push to end
                if let Some(idx) = self.lanes.iter().position(|l| l.is_none()) {
                    self.lanes[idx] = Some(oid);
                    idx
                } else {
                    self.lanes.push(Some(oid));
                    self.lanes.len() - 1
                }
            }
        } else {
            // Uncommitted changes
            0
        };

        let node_symbol = if commit.is_head || commit.is_uncommitted {
            '◉'
        } else {
            '●'
        };

        // Determine parents
        let parents = &commit.parents;

        // Parent 0 replaces current commit in commit_lane
        if !parents.is_empty() && oid_opt.is_some() {
            self.lanes[commit_lane] = Some(parents[0]);
        } else if oid_opt.is_some() {
            // No parents (root commit) -> free lane
            self.lanes[commit_lane] = None;
        }

