        };

        repo.diff_tree_to_tree(parent_tree.as_ref(), Some(&commit_tree), Some(&mut opts))?
    } else {
        return Ok(DiffSummary {
            files_changed: 0,
            total_additions: 0,
            total_deletions: 0,
            files: Vec::new(),
        });
    };

    let stats = diff.stats()?;
    let files_changed = stats.files_changed();
    let total_additions = stats.insertions();
    let total_deletions = stats.deletions();

    let mut files = Vec::new();

    for i in 0..diff.deltas().len().min(50) {
        if let Some(delta) = diff.get_delta(i) {
            let status_char = match delta.status() {
                Delta::Added => 'A',
                Delta::Deleted => 'D',
                Delta::Modified => 'M',
                Delta::Renamed => 'R',
                _ => 'M',
            };

            let path = delta
                .new_file()
                .path()
                .or_else(|| delta.old_file().path())
                .map(|p| p.to_string_lossy().to_string())
                .unwrap_or_default();

            let is_binary = delta.is_binary();

            let (additions, deletions) = if is_binary {
                (0, 0)
            } else {
                let mut add = 0;
                let mut del = 0;
                if let Ok(patch) = git2::Patch::from_diff(&diff, i) {
                    if let Some(p) = patch {
                        if let Ok((_, a, d)) = p.line_stats() {
                            add = a;
                            del = d;
                        }
                    }
                }
                (add, del)
            };

            files.push(FileStat {
                status_char,
                path,
                additions,
                deletions,
                is_binary,
            });
        }
    }

    Ok(DiffSummary {
        files_changed,
        total_additions,
        total_deletions,
        files,
    })
}

