            author_name: "".to_string(),
            author_email: "".to_string(),
            date: "".to_string(),
            datetime: "".to_string(),
            summary: format!("uncommitted changes ({})", uncommitted_count),
            body: "".to_string(),
            is_head: true,
            is_uncommitted: true,
            uncommitted_count,
            branches: Vec::new(),
            active_branch_idx: 0,
        });
    }

    // 2. Revwalk all branches
    let mut revwalk = repo.revwalk()?;
    revwalk.set_sorting(git2::Sort::TOPOLOGICAL | git2::Sort::TIME)?;

    if let Ok(refs) = repo.references() {
        for r in refs.flatten() {
            if r.is_branch() || r.is_remote() {
                if let Some(target) = r.target() {
                    let _ = revwalk.push(target);
                }
            }
        }
    }
    if let Some(h) = head_oid {
        let _ = revwalk.push(h);
    }

    let mut seen = HashSet::new();

    for oid_res in revwalk {
        if commits.len() >= 500 {
            break;
        }
        let oid = match oid_res {
            Ok(o) => o,
            Err(_) => continue,
        };

        if !seen.insert(oid) {
            continue;
        }

        let commit = match repo.find_commit(oid) {
            Ok(c) => c,
            Err(_) => continue,
        };

        let is_head = head_oid == Some(oid);
        let short_oid = oid.to_string()[..7].to_string();

        let author = commit.author();
        let author_name = author.name().unwrap_or("").to_string();
        let author_email = author.email().unwrap_or("").to_string();

        let time_sec = commit.time().seconds();
        let naive = chrono::DateTime::from_timestamp(time_sec, 0)
            .unwrap_or_default()
            .naive_local();
        let date = naive.format("%Y-%m-%d").to_string();
        let datetime = naive.format("%Y-%m-%d %H:%M:%S").to_string();

        let summary = commit.summary().unwrap_or("").to_string();
        let body = commit.body().unwrap_or("").to_string();

        let parents: Vec<Oid> = commit.parent_ids().collect();

        let mut branches = branch_map.get(&oid).cloned().unwrap_or_default();

        branches.sort_by(|a, b| {
            if a.is_head != b.is_head {
                return b.is_head.cmp(&a.is_head);
            }
            if a.local_name.is_some() != b.local_name.is_some() {
                return b.local_name.is_some().cmp(&a.local_name.is_some());
            }
            a.display_label.cmp(&b.display_label)
        });

        commits.push(CommitItem {
            oid: Some(oid),
            short_oid,
            parents,
            author_name,
            author_email,
            date,
            datetime,
            summary,
            body,
            is_head,
            is_uncommitted: false,
            uncommitted_count: 0,
            branches,
            active_branch_idx: 0,
        });
    }

    Ok(commits)
}

fn collect_branch_labels(
    repo: &Repository,
) -> Result<HashMap<Oid, Vec<BranchLabel>>, anyhow::Error> {
    let mut map: HashMap<Oid, Vec<BranchLabel>> = HashMap::new();

    let mut local_branches: HashMap<String, (Oid, bool)> = HashMap::new();
    if let Ok(branches) = repo.branches(Some(git2::BranchType::Local)) {
        for b in branches.flatten() {
            if let (Ok(Some(name)), Ok(Some(target))) = (b.0.name(), b.0.get().target()) {
                let is_head = b.0.is_head();
                local_branches.insert(name.to_string(), (target, is_head));
            }
        }
    }

    let mut remote_branches: HashMap<(String, String), Oid> = HashMap::new();
    if let Ok(branches) = repo.branches(Some(git2::BranchType::Remote)) {
        for b in branches.flatten() {
            if let (Ok(Some(full_name)), Ok(Some(target))) = (b.0.name(), b.0.get().target()) {
                let parts: Vec<&str> = full_name.splitn(2, '/').collect();
                if parts.len() == 2 {
                    remote_branches.insert((parts[0].to_string(), parts[1].to_string()), target);
                }
            }
        }
    }

    let mut processed_remotes = HashSet::new();

    for (local_name, (target, is_head)) in &local_branches {
        let mut display_label = local_name.clone();
        let remote_key = ("origin".to_string(), local_name.clone());

        if let Some(&remote_target) = remote_branches.get(&remote_key) {
            if remote_target == *target {
                display_label = format!("{} ↔ origin", local_name);
                processed_remotes.insert(remote_key);
            }
        }

        map.entry(*target).or_default().push(BranchLabel {
            display_label,
            local_name: Some(local_name.clone()),
            remote_ref: None,
            is_head: *is_head,
        });
    }

    for ((remote, branch_name), target) in &remote_branches {
        if processed_remotes.contains(&(remote.clone(), branch_name.clone())) {
            continue;
        }

        let full_remote_ref = format!("{}/{}", remote, branch_name);
        map.entry(*target).or_default().push(BranchLabel {
            display_label: full_remote_ref.clone(),
            local_name: None,
            remote_ref: Some(full_remote_ref),
            is_head: false,
        });
    }

    Ok(map)
}

pub fn get_diff_summary(
    repo: &Repository,
    commit_item: &CommitItem,
) -> Result<DiffSummary, anyhow::Error> {
    let mut opts = DiffOptions::new();
    opts.ignore_filemode(true);

    let diff = if commit_item.is_uncommitted {
        let head_tree = repo.head().ok().and_then(|h| h.peel_to_tree().ok());
        repo.diff_tree_to_workdir_with_index(head_tree.as_ref(), Some(&mut opts))?
    } else if let Some(oid) = commit_item.oid {
        let commit = repo.find_commit(oid)?;
        let commit_tree = commit.tree()?;

        let parent_tree = if commit.parent_count() > 0 {
            Some(commit.parent(0)?.tree()?)
        } else {
            None
        };

        repo.diff_tree_to_tree(parent_tree.as_ref(), Some(&commit_tree), Some(&mut opts))?
    } else {
        return Ok(DiffSummary {
            files_changed: 0,
            total_additions: 0,
            total_deletions: 0,
            files: Vec::new(),
        });
    };

    let stats = diff.stats()?;
    let files_changed = stats.files_changed();
    let total_additions = stats.insertions();
    let total_deletions = stats.deletions();

    let mut files = Vec::new();

    for i in 0..diff.deltas().len().min(50) {
        if let Some(delta) = diff.get_delta(i) {
            let status_char = match delta.status() {
                Delta::Added => 'A',
                Delta::Deleted => 'D',
                Delta::Modified => 'M',
                Delta::Renamed => 'R',
                _ => 'M',
            };

            let path = delta
                .new_file()
                .path()
                .or_else(|| delta.old_file().path())
                .map(|p| p.to_string_lossy().to_string())
                .unwrap_or_default();

            let is_binary = delta.is_binary();

            let (additions, deletions) = if is_binary {
                (0, 0)
            } else {
                let mut add = 0;
                let mut del = 0;
                if let Ok(patch) = git2::Patch::from_diff(&diff, i) {
                    if let Some(p) = patch {
                        if let Ok((_, a, d)) = p.line_stats() {
                            add = a;
                            del = d;
                        }
                    }
                }
                (add, del)
            };

            files.push(FileStat {
                status_char,
                path,
                additions,
                deletions,
                is_binary,
            });
        }
    }

    Ok(DiffSummary {
        files_changed,
        total_additions,
        total_deletions,
        files,
    })
}

pub fn checkout_branch_or_commit(
    repo: &Repository,
    commit_item: &CommitItem,
    branch_label: Option<&BranchLabel>,
) -> Result<String, anyhow::Error> {
    if let Some(label) = branch_label {
        if let Some(ref local_name) = label.local_name {
            let refname = format!("refs/heads/{}", local_name);
            let obj = repo.revparse_single(&refname)?;
            repo.checkout_tree(&obj, Some(git2::build::CheckoutBuilder::new().safe()))?;
            repo.set_head(&refname)?;
            return Ok(format!("Checked out branch '{}'", local_name));
        } else if let Some(ref remote_ref) = label.remote_ref {
            let parts: Vec<&str> = remote_ref.splitn(2, '/').collect();
            let local_name = if parts.len() == 2 { parts[1] } else { remote_ref };

            let target_oid = commit_item.oid.ok_or_else(|| anyhow::anyhow!("No OID"))?;
            let commit = repo.find_commit(target_oid)?;

            let local_refname = format!("refs/heads/{}", local_name);
            if repo.find_branch(local_name, git2::BranchType::Local).is_ok() {
                repo.reference(&local_refname, target_oid, true, "checkout remote branch")?;
            } else {
                repo.branch(local_name, &commit, true)?;
                if parts.len() == 2 {
                    if let Ok(mut b_ref) = repo.find_branch(local_name, git2::BranchType::Local) {
                        let _ = b_ref.set_upstream(Some(remote_ref));
                    }
                }
            };

            let obj = repo.revparse_single(&local_refname)?;
            repo.checkout_tree(&obj, Some(git2::build::CheckoutBuilder::new().safe()))?;
            repo.set_head(&local_refname)?;

            return Ok(format!("Checked out branch '{}'", local_name));
        }
    }

    if let Some(oid) = commit_item.oid {
        let commit = repo.find_commit(oid)?;
        repo.checkout_tree(commit.as_object(), Some(git2::build::CheckoutBuilder::new().safe()))?;
        repo.set_head_detached(oid)?;
        return Ok(format!("Checked out {}", &oid.to_string()[..7]));
    }

    Err(anyhow::anyhow!("Cannot checkout"))
}

pub fn create_branch(
    repo: &Repository,
    branch_name: &str,
    target_oid: Oid,
) -> Result<(), anyhow::Error> {
    let commit = repo.find_commit(target_oid)?;
    repo.branch(branch_name, &commit, false)?;
    Ok(())
}

pub fn delete_branch(repo: &Repository, branch_name: &str) -> Result<(), anyhow::Error> {
    let mut branch = repo.find_branch(branch_name, git2::BranchType::Local)?;
    branch.delete()?;
    Ok(())
}

pub fn fetch_origin() -> Result<String, anyhow::Error> {
    let output = std::process::Command::new("git")
        .args(["fetch", "origin"])
        .output()?;

    if output.status.success() {
        Ok("Fetched from origin".to_string())
    } else {
        let err_msg = String::from_utf8_lossy(&output.stderr).to_string();
        let err_summary = err_msg.lines().next().unwrap_or("fetch failed");
        Err(anyhow::anyhow!("git fetch failed: {}", err_summary))
    }
}
