                self.active_branch_idx += 1;
            }
        }
    }

    pub fn perform_checkout(&mut self) {
        if self.commits.is_empty() {
            return;
        }

        let commit_item = self.commits[self.selected_commit_idx].clone();
        let branch_label = commit_item.branches.get(self.active_branch_idx);

        match checkout_branch_or_commit(&self.repo, &commit_item, branch_label) {
