            let mut matches = Vec::new();

            for c in &self.commits {
                for b in &c.branches {
                    let label = b.local_name.clone().unwrap_or_else(|| b.display_label.clone());
                    if is_fuzzy_match(&query, &label.to_lowercase()) {
