                        break;
                    }
                }
                if found {
                    self.update_diff();
                    break;
                }
            }
        }
        self.mode = Mode::Normal;
    }
}

fn is_fuzzy_match(query: &str, target: &str) -> bool {
    if target.contains(query) {
        return true;
    }
    let mut target_chars = target.chars();
    for q in query.chars() {
        if !target_chars.any(|t| t == q) {
            return false;
        }
    }
    true
}
