                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                }
            }
        }
    }
    Ok(())
}

fn main() -> anyhow::Result<()> {
    parse_cli_args()?;

    let mut app = App::new()?;

    // Terminal setup
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let result = run_app(&mut terminal, &mut app);

    // Restore terminal
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    result
}

fn run_app(
    terminal: &mut Terminal<CrosstermBackend<io::Stdout>>,
    app: &mut App,
) -> anyhow::Result<()> {
    loop {
        terminal.draw(|f| ui::draw_ui(f, app))?;

        let now = Instant::now();
        if app.config.refresh.auto_refresh
            && now.duration_since(app.last_refresh)
                >= Duration::from_secs(app.config.refresh.refresh_interval)
        {
            app.refresh_state();
        }

        if app.config.refresh.auto_fetch
            && now.duration_since(app.last_fetch)
                >= Duration::from_secs(app.config.refresh.fetch_interval)
        {
            if let Ok(msg) = crate::git::fetch_origin() {
                app.status_msg = Some((msg, false));
                app.refresh_state();
            }
            app.last_fetch = Instant::now();
        }

        if event::poll(Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                if key.kind != KeyEventKind::Press {
                    continue;
                }

                if app.mode != Mode::Error(String::new()) && app.status_msg.is_some() {
                    app.status_msg = None;
                }

                match &app.mode {
                    Mode::Normal => match (key.code, key.modifiers) {
                        (KeyCode::Char('q'), KeyModifiers::NONE) | (KeyCode::Esc, _) => break,
                        (KeyCode::Char('j'), KeyModifiers::NONE) | (KeyCode::Down, _) => app.move_down(),
                        (KeyCode::Char('k'), KeyModifiers::NONE) | (KeyCode::Up, _) => app.move_up(),
                        (KeyCode::Char(']'), _) | (KeyCode::Tab, _) => app.jump_next_branch(),
                        (KeyCode::Char('['), _) | (KeyCode::BackTab, _) => app.jump_prev_branch(),
                        (KeyCode::Char('h'), KeyModifiers::NONE) | (KeyCode::Left, _) => app.move_left_branch(),
                        (KeyCode::Char('l'), KeyModifiers::NONE) | (KeyCode::Right, _) => app.move_right_branch(),
                        (KeyCode::Char('d'), KeyModifiers::CONTROL) => {
                            for _ in 0..10 { app.move_down(); }
                        }
                        (KeyCode::Char('u'), KeyModifiers::CONTROL) => {
                            for _ in 0..10 { app.move_up(); }
                        }
                        (KeyCode::Char('g'), KeyModifiers::NONE) | (KeyCode::Home, _) => {
                            app.selected_commit_idx = 0;
                            app.active_branch_idx = 0;
                            app.update_diff();
                        }
                        (KeyCode::Char('G'), _) | (KeyCode::End, _) => {
                            if !app.commits.is_empty() {
                                app.selected_commit_idx = app.commits.len() - 1;
                                app.active_branch_idx = 0;
                                app.update_diff();
                            }
                        }
                        (KeyCode::Char('@'), _) => app.jump_to_head(),
                        (KeyCode::Enter, _) => app.perform_checkout(),
                        (KeyCode::Char('b'), KeyModifiers::NONE) => {
                            app.new_branch_input.clear();
                            app.mode = Mode::NewBranch;
                        }
                        (KeyCode::Char('d'), KeyModifiers::NONE) => {
                            if !app.commits.is_empty() {
                                let commit = &app.commits[app.selected_commit_idx];
                                if let Some(b) = commit.branches.get(app.active_branch_idx) {
                                    if b.local_name.is_some() && !b.is_head {
                                        app.mode = Mode::ConfirmDelete;
                                    }
                                }
                            }
                        }
                        (KeyCode::Char('f'), KeyModifiers::NONE) => {
                            app.status_msg = Some(("Fetching from origin...".to_string(), false));
                            terminal.draw(|f| ui::draw_ui(f, app))?;
                            match crate::git::fetch_origin() {
                                Ok(msg) => app.status_msg = Some((msg, false)),
                                Err(e) => app.status_msg = Some((e.to_string(), true)),
                            }
                            app.refresh_state();
                        }
                        (KeyCode::Char('/'), KeyModifiers::NONE) => {
                            app.search_query.clear();
                            app.search_selected_idx = 0;
                            app.update_search();
                            app.mode = Mode::Search;
                        }
                        (KeyCode::Char('R'), _) => app.refresh_state(),
                        (KeyCode::Char('?'), _) => app.mode = Mode::Help,
                        _ => {}
                    },

                    Mode::Help => match key.code {
                        KeyCode::Char('q') | KeyCode::Char('?') | KeyCode::Esc => {
                            app.mode = Mode::Normal;
                        }
                        _ => {}
                    },

                    Mode::Error(_) => match key.code {
                        KeyCode::Enter | KeyCode::Esc => {
                            app.mode = Mode::Normal;
                        }
                        _ => {}
                    },

                    Mode::NewBranch => match key.code {
                        KeyCode::Esc => app.mode = Mode::Normal,
                        KeyCode::Enter => app.perform_create_branch(),
                        KeyCode::Backspace => {
                            app.new_branch_input.pop();
                        }
                        KeyCode::Char(c) => {
                            app.new_branch_input.push(c);
                        }
                        _ => {}
                    },

                    Mode::ConfirmDelete => match key.code {
                        KeyCode::Char('y') | KeyCode::Char('Y') => app.perform_delete_branch(),
                        KeyCode::Char('n') | KeyCode::Char('N') | KeyCode::Esc => {
                            app.mode = Mode::Normal;
                        }
                        _ => {}
                    },

                    Mode::Search => match (key.code, key.modifiers) {
                        (KeyCode::Esc, _) => app.mode = Mode::Normal,
                        (KeyCode::Enter, _) => app.confirm_search_selection(),
                        (KeyCode::Backspace, _) => {
                            if app.search_query.is_empty() {
                                app.mode = Mode::Normal;
                            } else {
                                app.search_query.pop();
                                app.update_search();
                            }
                        }
                        (KeyCode::Up, _) | (KeyCode::Char('k'), KeyModifiers::CONTROL) => {
                            if app.search_selected_idx > 0 {
                                app.search_selected_idx -= 1;
                            }
                        }
                        (KeyCode::Down, _) | (KeyCode::Char('j'), KeyModifiers::CONTROL) => {
                            if !app.search_results.is_empty()
                                && app.search_selected_idx < app.search_results.len() - 1
                            {
                                app.search_selected_idx += 1;
                            }
                        }
                        (KeyCode::Char(c), KeyModifiers::NONE) => {
                            app.search_query.push(c);
                            app.update_search();
                        }
                        _ => {}
                    },
                }
            }
        }
    }

    Ok(())
}
