                    Mode::Help => match key.code {
                        KeyCode::Char('q') | KeyCode::Char('?') | KeyCode::Esc => {
                            app.mode = Mode::Normal;
                        }
                        _ => {}
                    },

                    Mode::Error(_) => match key.code {
                        KeyCode::Enter | KeyCode::Esc => {
                            app.mode = Mode::Normal;
                        }
                        _ => {}
                    },

                    Mode::NewBranch => match key.code {
                        KeyCode::Esc => app.mode = Mode::Normal,
                        KeyCode::Enter => app.perform_create_branch(),
                        KeyCode::Backspace => {
                            app.new_branch_input.pop();
                        }
                        KeyCode::Char(c) => {
                            app.new_branch_input.push(c);
                        }
                        _ => {}
                    },

                    Mode::ConfirmDelete => match key.code {
                        KeyCode::Char('y') | KeyCode::Char('Y') => app.perform_delete_branch(),
                        KeyCode::Char('n') | KeyCode::Char('N') | KeyCode::Esc => {
                            app.mode = Mode::Normal;
                        }
                        _ => {}
                    },

                    Mode::Search => match (key.code, key.modifiers) {
                        (KeyCode::Esc, _) => app.mode = Mode::Normal,
                        (KeyCode::Enter, _) => app.confirm_search_selection(),
                        (KeyCode::Backspace, _) => {
                            if app.search_query.is_empty() {
                                app.mode = Mode::Normal;
                            } else {
                                app.search_query.pop();
                                app.update_search();
                            }
                        }
                        (KeyCode::Up, _) | (KeyCode::Char('k'), KeyModifiers::CONTROL) => {
                            if app.search_selected_idx > 0 {
                                app.search_selected_idx -= 1;
                            }
                        }
                        (KeyCode::Down, _) | (KeyCode::Char('j'), KeyModifiers::CONTROL) => {
                            if !app.search_results.is_empty()
                                && app.search_selected_idx < app.search_results.len() - 1
                            {
                                app.search_selected_idx += 1;
                            }
                        }
                        (KeyCode::Char(c), KeyModifiers::NONE) => {
                            app.search_query.push(c);
                            app.update_search();
                        }
                        _ => {}
                    },
                }
            }
        }
    }

    Ok(())
}
