actions.command:
cat << 'EOF' > src/ui.rs
use crate::app::{App, Mode};
use ratatui::{
    layout::{Alignment, Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, Clear, List, ListItem, Paragraph},
    Frame,
};

pub fn draw_ui(f: &mut Frame, app: &mut App) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage(70),
            Constraint::Percentage(30),
            Constraint::Length(1),
        ])
        .split(f.area());

    let top_chunk = chunks[0];
    let bottom_chunk = chunks[1];
    let status_chunk = chunks[2];

    let bottom_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(50), Constraint::Percentage(50)])
        .split(bottom_chunk);

    draw_commits_panel(f, app, top_chunk);
    draw_commit_detail_panel(f, app, bottom_chunks[0]);
    draw_changed_files_panel(f, app, bottom_chunks[1]);
    draw_status_line(f, app, status_chunk);

    // Overlays
    match &app.mode {
        Mode::Help => draw_help_popup(f, app, f.area()),
        Mode::Search => draw_search_popup(f, app, f.area()),
        Mode::NewBranch => draw_new_branch_popup(f, app, f.area()),
        Mode::ConfirmDelete => draw_confirm_delete_popup(f, app, f.area()),
        _ => {}
    }
}

fn draw_commits_panel(f: &mut Frame, app: &mut App, area: Rect) {
    let block = Block::default()
        .title("Commits")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::DarkGray));

    let inner = block.inner(area);
    f.render_widget(block, area);

    if app.commits.is_empty() {
        return;
    }

    let list_height = inner.height as usize;
    let mut start_idx = 0;
    if app.selected_commit_idx >= list_height {
        start_idx = app.selected_commit_idx - list_height + 1;
    }
    let end_idx = (start_idx + list_height).min(app.commits.len());

    let available_width = inner.width as usize;

    let mut items = Vec::new();

    for i in start_idx..end_idx {
        let commit = &app.commits[i];
        let graph_row = &app.graph_rows[i];
        let is_selected = i == app.selected_commit_idx;

        let mut spans = Vec::new();

        // 1. Graph prefix
        for cell in &graph_row.cells {
            spans.push(Span::styled(
                cell.symbol.to_string(),
                Style::default().fg(cell.color),
            ));
        }
        spans.push(Span::raw(" "));

        // 2. Branch label
        if !commit.branches.is_empty() {
            let active_branch = commit.branches.get(commit.active_branch_idx);
            let display_text = if let Some(b) = active_branch {
                &b.display_label
            } else {
                &commit.branches[0].display_label
            };

            let label_str = if commit.branches.len() > 1 {
                format!("[{}] +{}", display_text, commit.branches.len() - 1)
            } else {
                format!("[{}]", display_text)
            };

            spans.push(Span::styled(
                label_str,
                Style::default()
                    .fg(Color::Indexed(12))
                    .add_modifier(Modifier::BOLD),
            ));
            spans.push(Span::raw(" "));
        }

        // 3. Summary
        spans.push(Span::raw(commit.summary.clone()));

        // Combine into line to calculate width
        let left_line = Line::from(spans);

        // Right side info: Date, Author, Hash
        let date_str = &commit.date;
        let author_str = &commit.author_name;
        let hash_str = &commit.short_oid;

        let date_span = Span::styled(date_str.clone(), Style::default().fg(Color::DarkGray));
        let author_span = Span::styled(
            format!("{:8}", author_str.chars().take(8).collect::<String>()),
            Style::default().fg(Color::Cyan),
        );
        let hash_span = Span::styled(hash_str.clone(), Style::default().fg(Color::Yellow));

        // Check horizontal space
        let mut line_spans = left_line.spans;

        if available_width >= 89 {
            // Show all: Date, Author, Hash
            let current_len: usize = line_spans.iter().map(|s| s.width()).sum();
            let right_width = 2 + 10 + 2 + 8 + 2 + 7 + 1; // 32
            if current_len + right_width < available_width {
                let pad = available_width - current_len - right_width;
                line_spans.push(Span::raw(" ".repeat(pad)));
                line_spans.push(Span::raw("  "));
                line_spans.push(date_span);
                line_spans.push(Span::raw("  "));
                line_spans.push(author_span);
                line_spans.push(Span::raw("  "));
                line_spans.push(hash_span);
                line_spans.push(Span::raw(" "));
            }
        } else if available_width >= 81 {
            // Show Date, Author
            let current_len: usize = line_spans.iter().map(|s| s.width()).sum();
            let right_width = 2 + 10 + 2 + 8 + 1; // 23
            if current_len + right_width < available_width {
                let pad = available_width - current_len - right_width;
                line_spans.push(Span::raw(" ".repeat(pad)));
                line_spans.push(Span::raw("  "));
                line_spans.push(date_span);
                line_spans.push(Span::raw("  "));
                line_spans.push(author_span);
                line_spans.push(Span::raw(" "));
            }
        } else if available_width >= 69 {
            // Show Author
            let current_len: usize = line_spans.iter().map(|s| s.width()).sum();
            let right_width = 2 + 8 + 1; // 11
            if current_len + right_width < available_width {
                let pad = available_width - current_len - right_width;
                line_spans.push(Span::raw(" ".repeat(pad)));
                line_spans.push(Span::raw("  "));
                line_spans.push(author_span);
                line_spans.push(Span::raw(" "));
            }
        }

        let mut row_style = Style::default();
        if is_selected {
            row_style = row_style.bg(Color::DarkGray);
        }

        items.push(ListItem::new(Line::from(line_spans)).style(row_style));
    }

    let list = List::new(items);
    f.render_widget(list, inner);

    // Render floating Branches dropdown if selected commit has multiple branches
    if !app.commits.is_empty() {
        let sel_commit = &app.commits[app.selected_commit_idx];
        if sel_commit.branches.len() > 1 {
            draw_branches_dropdown(f, app, area);
        }
    }
}

fn draw_branches_dropdown(f: &mut Frame, app: &App, area: Rect) {
    let sel_commit = &app.commits[app.selected_commit_idx];
    let max_len = sel_commit
        .branches
        .iter()
        .map(|b| b.display_label.len())
        .max()
        .unwrap_or(10);

    let popup_width = (max_len + 6).max(18) as u16;
    let popup_height = (sel_commit.branches.len() + 2).min(10) as u16;

    if area.width < popup_width + 4 {
        return;
    }

    let popup_rect = Rect {
        x: area.width - popup_width - 2,
        y: area.y + 2,
        width: popup_width,
        height: popup_height,
    };

    f.render_widget(Clear, popup_rect);

    let block = Block::default()
        .title("Branches")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::Blue));

    let items: Vec<ListItem> = sel_commit
        .branches
        .iter()
        .enumerate()
        .map(|(idx, b)| {
            let is_active = idx == app.active_branch_idx;
            let prefix = if is_active { "▶ " } else { "  " };
            let text = format!("{}{}", prefix, b.display_label);
            let style = if is_active {
                Style::default().fg(Color::Black).bg(Color::Blue)
            } else {
                Style::default().fg(Color::White)
            };
            ListItem::new(text).style(style)
        })
        .collect();

    let list = List::new(items).block(block);
    f.render_widget(list, popup_rect);
}

fn draw_commit_detail_panel(f: &mut Frame, app: &App, area: Rect) {
    let block = Block::default()
        .title("Commit Detail")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::DarkGray));

    let inner = block.inner(area);
    f.render_widget(block, area);

    if app.commits.is_empty() {
        return;
    }

    let commit = &app.commits[app.selected_commit_idx];
    let mut lines = Vec::new();

    if commit.is_uncommitted {
        lines.push(Line::from(Span::styled(
            "Uncommitted Changes",
            Style::default().add_modifier(Modifier::BOLD),
        )));
        lines.push(Line::from(""));
        lines.push(Line::from(format!(
            "{} files with changes",
            commit.uncommitted_count
        )));
    } else {
        if let Some(oid) = commit.oid {
            lines.push(Line::from(vec![
                Span::styled("Commit: ", Style::default().add_modifier(Modifier::BOLD)),
                Span::styled(oid.to_string(), Style::default().fg(Color::DarkGray)),
            ]));
        }
        lines.push(Line::from(vec![
            Span::styled("Author: ", Style::default().add_modifier(Modifier::BOLD)),
            Span::styled(
                format!("{} <{}>", commit.author_name, commit.author_email),
                Style::default().fg(Color::DarkGray),
            ),
        ]));
        lines.push(Line::from(vec![
            Span::styled("Date:   ", Style::default().add_modifier(Modifier::BOLD)),
            Span::styled(&commit.datetime, Style::default().fg(Color::DarkGray)),
        ]));

        if !commit.parents.is_empty() {
            let parents_str = commit
                .parents
                .iter()
                .map(|p| p.to_string()[..7].to_string())
                .collect::<Vec<String>>()
                .join(", ");
            lines.push(Line::from(vec![
                Span::styled("Parent: ", Style::default().add_modifier(Modifier::BOLD)),
                Span::styled(parents_str, Style::default().fg(Color::DarkGray)),
            ]));
        }

        lines.push(Line::from(""));
        lines.push(Line::from(commit.summary.clone()));

        if !commit.body.is_empty() {
            lines.push(Line::from(""));
            for body_line in commit.body.lines() {
                lines.push(Line::from(body_line.to_string()));
            }
        }
    }

    let paragraph = Paragraph::new(lines);
    f.render_widget(paragraph, inner);
}

fn draw_changed_files_panel(f: &mut Frame, app: &App, area: Rect) {
    let block = Block::default()
        .title("Changed Files")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::DarkGray));

    let inner = block.inner(area);
    f.render_widget(block, area);

    if let Some(ref diff) = app.current_diff {
        let mut lines = Vec::new();

        lines.push(Line::from(vec![
            Span::raw(format!("{} files changed  ", diff.files_changed)),
            Span::styled(
                format!("+{}", diff.total_additions),
                Style::default().fg(Color::Green),
            ),
            Span::raw(" "),
            Span::styled(
                format!("-{}", diff.total_deletions),
                Style::default().fg(Color::Red),
            ),
        ]));
        lines.push(Line::from(""));

        for file in &diff.files {
            let status_color = match file.status_char {
                'A' => Color::Green,
                'D' => Color::Red,
                'M' => Color::Yellow,
                'R' => Color::Blue,
                _ => Color::White,
            };

            let mut file_spans = vec![
                Span::styled(format!(" {} ", file.status_char), Style::default().fg(status_color)),
                Span::raw(format!("{} ", file.path)),
            ];

            if !file.is_binary {
                file_spans.push(Span::styled(
                    format!("+{}", file.additions),
                    Style::default().fg(Color::Green),
                ));
                file_spans.push(Span::raw(" "));
                file_spans.push(Span::styled(
                    format!("-{}", file.deletions),
                    Style::default().fg(Color::Red),
                ));
            }

            lines.push(Line::from(file_spans));
        }

        let paragraph = Paragraph::new(lines);
        f.render_widget(paragraph, inner);
    }
}

fn draw_status_line(f: &mut Frame, app: &App, area: Rect) {
    let mut left_spans = vec![
        Span::raw(" "),
        Span::styled(&app.repo_info.repo_name, Style::default().fg(Color::White)),
        Span::raw("   "),
        Span::styled(
            &app.repo_info.current_branch_name,
            Style::default().fg(Color::Green),
        ),
        Span::raw("   "),
    ];

    let mut right_tag = "";
    let mut right_color = Color::Yellow;

    if let Mode::Error(ref err) = app.mode {
        left_spans.push(Span::styled(
            format!("{}    Esc/Enter close", err),
            Style::default().fg(Color::Red),
        ));
        right_tag = "ERROR";
        right_color = Color::Red;
    } else if let Some((ref msg, is_err)) = app.status_msg {
        let color = if is_err { Color::Red } else { Color::White };
        left_spans.push(Span::styled(msg, Style::default().fg(color)));
        if is_err {
            right_tag = "ERROR";
            right_color = Color::Red;
        }
    } else {
        let hint = match app.mode {
            Mode::Normal => "j/k move  Enter checkout  b branch  f fetch  ? help  q quit",
            Mode::Search => "Enter confirm  Esc cancel",
            Mode::NewBranch => "Enter confirm  Esc cancel",
            Mode::ConfirmDelete => "y yes  n no",
            Mode::Help => "Esc/q close help",
            Mode::Error(_) => "",
        };

        match app.mode {
            Mode::Search | Mode::NewBranch => {
                right_tag = "INPUT";
                right_color = Color::Yellow;
            }
            Mode::ConfirmDelete => {
                right_tag = "CONFIRM";
                right_color = Color::Yellow;
            }
            Mode::Help => {
                right_tag = "HELP";
                right_color = Color::Cyan;
            }
            _ => {}
        }

        left_spans.push(Span::styled(hint, Style::default().fg(Color::DarkGray)));
    }

    let left_line = Line::from(left_spans);
    f.render_widget(Paragraph::new(left_line), area);

    if !right_tag.is_empty() {
        let right_paragraph = Paragraph::new(Line::from(vec![
            Span::styled(right_tag, Style::default().fg(right_color).add_modifier(Modifier::BOLD)),
            Span::raw(" "),
        ]))
        .alignment(Alignment::Right);
        f.render_widget(right_paragraph, area);
    }
}

fn draw_help_popup(f: &mut Frame, _app: &App, area: Rect) {
    let popup_width = 72;
    let popup_height = 28;

    let popup_rect = Rect {
        x: (area.width.saturating_sub(popup_width)) / 2,
        y: (area.height.saturating_sub(popup_height)) / 2,
        width: popup_width.min(area.width),
        height: popup_height.min(area.height),
    };

    f.render_widget(Clear, popup_rect);

    let block = Block::default()
        .title("Help")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::Cyan));

    let help_text = vec![
        Line::from(Span::styled("Navigation", Style::default().add_modifier(Modifier::BOLD))),
        Line::from("  j / ↓      Move down"),
        Line::from("  k / ↑      Move up"),
        Line::from("  ] / Tab    Select next branch"),
        Line::from("  [ / S-Tab  Select previous branch"),
        Line::from("  h / ←      Select left branch (same commit)"),
        Line::from("  l / →      Select right branch (same commit)"),
        Line::from("  Ctrl+d     Page down"),
        Line::from("  Ctrl+u     Page up"),
        Line::from("  g / Home   Go to top"),
        Line::from("  G / End    Go to bottom"),
        Line::from("  @          Jump to HEAD (current branch)"),
        Line::from(""),
        Line::from(Span::styled("Git Operations", Style::default().add_modifier(Modifier::BOLD))),
        Line::from("  Enter      Checkout selected branch/commit"),
        Line::from("  b          Create new branch"),
        Line::from("  d          Delete branch"),
        Line::from("  f          Fetch from origin"),
        Line::from(""),
        Line::from(Span::styled("Search", Style::default().add_modifier(Modifier::BOLD))),
        Line::from("  /          Search branches"),
        Line::from("  ↑ / C-k    Select previous result"),
        Line::from("  ↓ / C-j    Select next result"),
        Line::from("  Enter      Jump to selected branch"),
        Line::from("  Esc        Cancel search"),
        Line::from(""),
        Line::from(Span::styled("Other", Style::default().add_modifier(Modifier::BOLD))),
        Line::from("  R          Refresh"),
        Line::from("  ?          Toggle this help"),
    ];

    let paragraph = Paragraph::new(help_text).block(block);
    f.render_widget(paragraph, popup_rect);
}

fn draw_search_popup(f: &mut Frame, app: &App, area: Rect) {
    let popup_width = 71;
    let popup_height = (app.search_results.len() + 5).clamp(4, 12) as u16;

    let popup_rect = Rect {
        x: (area.width.saturating_sub(popup_width)) / 2,
        y: (area.height.saturating_sub(popup_height)) / 2,
        width: popup_width.min(area.width),
        height: popup_height.min(area.height),
    };

    f.render_widget(Clear, popup_rect);

    let block = Block::default()
        .title("Search branches")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::Cyan));

    let mut lines = Vec::new();
    lines.push(Line::from(format!("  {}_", app.search_query)));

    if app.search_results.is_empty() && !app.search_query.is_empty() {
        lines.push(Line::from("  No matches"));
    } else if app.search_query.is_empty() && app.search_results.is_empty() {
        lines.push(Line::from("  Enter: confirm  Esc: cancel"));
    } else {
        lines.push(Line::from("─".repeat(popup_width as usize - 2)));
        for (idx, result) in app.search_results.iter().take(6).enumerate() {
            let is_sel = idx == app.search_selected_idx;
            let prefix = if is_sel { "▶ " } else { "  " };
            lines.push(Line::from(format!("{}{}", prefix, result)));
        }
        lines.push(Line::from("  ↑↓: select  Enter: jump  Esc: cancel"));
    }

    let paragraph = Paragraph::new(lines).block(block);
    f.render_widget(paragraph, popup_rect);
}

fn draw_new_branch_popup(f: &mut Frame, app: &App, area: Rect) {
    let popup_width = 60;
    let popup_height = 7;

    let popup_rect = Rect {
        x: (area.width.saturating_sub(popup_width)) / 2,
        y: (area.height.saturating_sub(popup_height)) / 2,
        width: popup_width.min(area.width),
        height: popup_height.min(area.height),
    };

    f.render_widget(Clear, popup_rect);

    let block = Block::default()
        .title("New Branch Name")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::Cyan));

    let text = vec![
        Line::from(""),
        Line::from(format!("  {}_", app.new_branch_input)),
        Line::from(""),
        Line::from("  Enter: confirm  Esc: cancel"),
    ];

    let paragraph = Paragraph::new(text).block(block);
    f.render_widget(paragraph, popup_rect);
}

fn draw_confirm_delete_popup(f: &mut Frame, app: &App, area: Rect) {
    let popup_width = 60;
    let popup_height = 7;

    let popup_rect = Rect {
        x: (area.width.saturating_sub(popup_width)) / 2,
        y: (area.height.saturating_sub(popup_height)) / 2,
        width: popup_width.min(area.width),
        height: popup_height.min(area.height),
    };

    f.render_widget(Clear, popup_rect);

    let block = Block::default()
        .title("Confirm")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::Cyan));

    let mut branch_name = "";
    if !app.commits.is_empty() {
        let commit = &app.commits[app.selected_commit_idx];
        if let Some(b) = commit.branches.get(app.active_branch_idx) {
            branch_name = b.local_name.as_deref().unwrap_or(&b.display_label);
        }
    }

    let text = vec![
        Line::from(""),
        Line::from(format!("  Delete branch '{}'?", branch_name)),
        Line::from(""),
        Line::from("  y: Yes  n: No"),
    ];

    let paragraph = Paragraph::new(text).block(block);
    f.render_widget(paragraph, popup_rect);
}
