use ratatui::style::Color;
use git2::Oid;

pub const BRANCH_COLORS: &[Color] = &[
    Color::Indexed(12), // LightBlue
    Color::Indexed(2),  // Green
    Color::Indexed(5),  // Magenta
    Color::Indexed(3),  // Yellow
    Color::Indexed(1),  // Red
    Color::Indexed(14), // LightCyan
    Color::Indexed(10), // LightGreen
    Color::Indexed(13), // LightMagenta
];

#[derive(Debug, Clone)]
pub struct GraphCell {
    pub symbol: char,
    pub color: Color,
}

#[derive(Debug, Clone)]
pub struct GraphRow {
    pub cells: Vec<GraphCell>,
}

pub struct GraphBuilder {
    lanes: Vec<Option<Oid>>,
}

impl GraphBuilder {
    pub fn new() -> Self {
        Self { lanes: Vec::new() }
    }

    pub fn build_rows(commits: &[crate::git::CommitItem]) -> Vec<GraphRow> {
        let mut builder = Self::new();
        let mut rows = Vec::new();

        for commit in commits {
            rows.push(builder.process_commit(commit));
        }

        rows
    }

    fn process_commit(&mut self, commit: &crate::git::CommitItem) -> GraphRow {
        let oid_opt = commit.oid;

        let commit_lane = if let Some(oid) = oid_opt {
            if let Some(idx) = self.lanes.iter().position(|l| *l == Some(oid)) {
                idx
            } else if let Some(idx) = self.lanes.iter().position(|l| l.is_none()) {
                self.lanes[idx] = Some(oid);
                idx
            } else {
                self.lanes.push(Some(oid));
                self.lanes.len() - 1
            }
        } else {
            0
        };

        let node_symbol = if commit.is_head || commit.is_uncommitted {
            '◉'
        } else {
            '●'
        };

        let parents = &commit.parents;

        if !parents.is_empty() && oid_opt.is_some() {
            self.lanes[commit_lane] = Some(parents[0]);
        } else if oid_opt.is_some() {
            self.lanes[commit_lane] = None;
        }

        let mut merge_lanes = Vec::new();
        for &p in parents.iter().skip(1) {
            if let Some(idx) = self.lanes.iter().position(|l| *l == Some(p)) {
                merge_lanes.push(idx);
            } else {
                let idx = if let Some(free_idx) = self.lanes.iter().position(|l| l.is_none()) {
                    self.lanes[free_idx] = Some(p);
                    free_idx
                } else {
                    self.lanes.push(Some(p));
                    self.lanes.len() - 1
                };
                merge_lanes.push(idx);
            }
        }

        let num_lanes = self.lanes.len().max(commit_lane + 1);
        let mut cells = Vec::new();

        // 1 leading space margin
        cells.push(GraphCell { symbol: ' ', color: Color::Reset });

        let max_merge_lane = merge_lanes.iter().max().cloned();

        for i in 0..num_lanes {
            let color = BRANCH_COLORS[i % BRANCH_COLORS.len()];

            if i == commit_lane {
                cells.push(GraphCell { symbol: node_symbol, color });

                if let Some(max_m) = max_merge_lane {
                    if max_m > commit_lane {
                        cells.push(GraphCell { symbol: '─', color });
                    } else {
                        cells.push(GraphCell { symbol: ' ', color: Color::Reset });
                    }
                } else {
                    cells.push(GraphCell { symbol: ' ', color: Color::Reset });
                }
            } else if merge_lanes.contains(&i) {
                cells.push(GraphCell { symbol: '╮', color });
                cells.push(GraphCell { symbol: ' ', color: Color::Reset });
            } else if max_merge_lane.map(|m| i > commit_lane && i < m).unwrap_or(false) {
                cells.push(GraphCell { symbol: '─', color: BRANCH_COLORS[commit_lane % BRANCH_COLORS.len()] });
                cells.push(GraphCell { symbol: '─', color: BRANCH_COLORS[commit_lane % BRANCH_COLORS.len()] });
            } else if self.lanes.get(i).and_then(|l| *l).is_some() {
                cells.push(GraphCell { symbol: '│', color });
                cells.push(GraphCell { symbol: ' ', color: Color::Reset });
            } else {
                cells.push(GraphCell { symbol: ' ', color: Color::Reset });
                cells.push(GraphCell { symbol: ' ', color: Color::Reset });
            }
        }

        while self.lanes.last() == Some(&None) {
            self.lanes.pop();
        }

        GraphRow { cells }
    }
}
EOF"}

