            if a.is_head != b.is_head {
                return b.is_head.cmp(&a.is_head);
            }
            if a.local_name.is_some() != b.local_name.is_some() {
                return b.local_name.is_some().cmp(&a.local_name.is_some());
            }
            a.display_label.cmp(&b.display_label)
        });

