            oid: Some(oid),
            short_oid,
            parents,
            author_name,
            author_email,
            date,
            datetime,
            summary,
            body,
            is_head,
            is_uncommitted: false,
            uncommitted_count: 0,
            branches,
            active_branch_idx: 0,
